create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Admin',created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,brand text,notes text,image_url text,price_5ml numeric(12,0),price_10ml numeric(12,0),price_35ml numeric(12,0),price_60ml numeric(12,0),price_100ml numeric(12,0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.admin_users enable row level security; alter table public.products enable row level security;
drop policy if exists "Admins can view their own admin record" on public.admin_users; create policy "Admins can view their own admin record" on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "Public can view active perfumes" on public.products; create policy "Public can view active perfumes" on public.products for select to anon,authenticated using(is_active=true or exists(select 1 from public.admin_users au where au.user_id=(select auth.uid())));
drop policy if exists "Admins can insert products" on public.products; create policy "Admins can insert products" on public.products for insert to authenticated with check(exists(select 1 from public.admin_users au where au.user_id=(select auth.uid())));
drop policy if exists "Admins can update products" on public.products; create policy "Admins can update products" on public.products for update to authenticated using(exists(select 1 from public.admin_users au where au.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users au where au.user_id=(select auth.uid())));
drop policy if exists "Admins can delete products" on public.products; create policy "Admins can delete products" on public.products for delete to authenticated using(exists(select 1 from public.admin_users au where au.user_id=(select auth.uid())));
grant select on public.products to anon,authenticated; grant insert,update,delete on public.products to authenticated; grant select on public.admin_users to authenticated;
